const { createUser, ValidationError } = require('../users');

test('converts numeric string age', () => {
  assert.deepStrictEqual(createUser({ name: 'Bo', age: '42' }), { name: 'Bo', age: 42 });
  assert.strictEqual(createUser({ name: 'Bo', age: 0 }).age, 0);
  assert.strictEqual(createUser({ name: 'Bo', age: '150' }).age, 150);
});

test('rejects invalid names', () => {
  for (const name of [undefined, null, '', '   ', 5]) {
    assert.throws(() => createUser({ name, age: 20 }), ValidationError);
  }
});

test('rejects invalid ages', () => {
  for (const age of [undefined, null, '', 'abc', '4.5', 4.5, -1, 151, '-1', '151', NaN, Infinity, true, []]) {
    assert.throws(() => createUser({ name: 'Bo', age }), ValidationError);
  }
});

test('rejects non-object input', () => {
  assert.throws(() => createUser(null), ValidationError);
  assert.throws(() => createUser(undefined), ValidationError);
});

